//! Validation against independent references (SOFA and SPICE).
//! Reference values are generated by `tests/reference/generate.py`.

#[rustfmt::skip]
#[path = "reference/data.rs"]
mod data;

use heavenly_core::{Epoch, Rotation, Transform, Vec3};
use heavenly_geo::earth::{self, EarthOrientation};
use heavenly_geo::{iau, Ellipsoid, Geodetic};

const MAS: f64 = core::f64::consts::PI / 180.0 / 3600.0 / 1000.0;

fn mat(m: &[f64; 9]) -> [[f64; 3]; 3] {
    [[m[0], m[1], m[2]], [m[3], m[4], m[5]], [m[6], m[7], m[8]]]
}

/// Angle in radians of the rotation taking `b` to `a`.
fn angle_between(a: [[f64; 3]; 3], b: [[f64; 3]; 3]) -> f64 {
    let mut d = [[0.0; 3]; 3];
    for i in 0..3 {
        for j in 0..3 {
            d[i][j] = (0..3).map(|k| a[i][k] * b[j][k]).sum();
        }
    }
    Rotation::from_matrix(d).unwrap().angle_rad()
}

#[test]
fn geodetic_matches_sofa() {
    let mut worst = (0.0f64, 0.0f64);
    for r in data::GEODETIC {
        let p = Vec3::new(r[0], r[1], r[2]);
        let g = Geodetic::from_cartesian(p, &Ellipsoid::WGS84).unwrap();
        let dlat = (g.latitude_rad - r[3]).abs();
        let mut dlon = (g.longitude_rad - r[4]).abs();
        if p.x.hypot(p.y) < 1e-3 {
            dlon = 0.0; // longitude is undefined on the axis
        }
        worst.0 = worst.0.max(dlat.max(dlon) * 6.4e6);
        worst.1 = worst.1.max((g.height_m - r[5]).abs());
        // Forward conversion round-trips.
        let back = Geodetic::new(r[3], r[4], r[5])
            .unwrap()
            .to_cartesian(&Ellipsoid::WGS84);
        assert!((back - p).norm() < 1e-6 * (1.0 + p.norm() / 1e7), "{r:?}");
    }
    // Sub-micrometre agreement in position and height.
    assert!(worst.0 < 1e-6 && worst.1 < 1e-6, "{worst:?}");
}

#[test]
fn geodetic_edge_cases() {
    let e = Ellipsoid::WGS84;
    let pole = Geodetic::from_cartesian(Vec3::new(0.0, 0.0, e.semi_minor_axis_m()), &e).unwrap();
    assert!((pole.latitude_rad - core::f64::consts::FRAC_PI_2).abs() < 1e-15);
    assert!(pole.height_m.abs() < 1e-6);
    assert!(Geodetic::from_cartesian(Vec3::ZERO, &e).is_err());
    assert!(Geodetic::from_degrees(91.0, 0.0, 0.0).is_err());

    let moon =
        Geodetic::from_cartesian(Vec3::new(0.0, 1_737_500.0, 0.0), &Ellipsoid::MOON).unwrap();
    assert!((moon.height_m - 100.0).abs() < 1e-9);
    assert!((moon.longitude_rad - core::f64::consts::FRAC_PI_2).abs() < 1e-15);

    // Mars round trip.
    let g = Geodetic::from_degrees(-4.5895, 137.4417, -4500.0).unwrap(); // Gale crater
    let p = g.to_cartesian(&Ellipsoid::MARS);
    let back = Geodetic::from_cartesian(p, &Ellipsoid::MARS).unwrap();
    assert!((back.latitude_rad - g.latitude_rad).abs() < 1e-14);
    assert!((back.height_m - g.height_m).abs() < 1e-7);
}

#[test]
fn enu_frame_axes() {
    let g = Geodetic::from_degrees(0.0, 90.0, 0.0).unwrap();
    let t = g.enu_to_body_fixed(&Ellipsoid::WGS84);
    // At (0°, 90°E): east is −x, north is +z, up is +y.
    let close = |a: Vec3, b: Vec3| (a - b).norm() < 1e-12;
    assert!(close(t.rotation.apply(Vec3::X), Vec3::new(-1.0, 0.0, 0.0)));
    assert!(close(t.rotation.apply(Vec3::Y), Vec3::Z));
    assert!(close(t.rotation.apply(Vec3::Z), Vec3::Y));
    assert!((t.translation_m - Vec3::new(0.0, 6_378_137.0, 0.0)).norm() < 1e-6);
}

#[test]
fn earth_orientation_matches_sofa_c2t06a() {
    let mut worst = 0.0f64;
    for (utc, dut1, xp, yp, m) in data::EARTH {
        let epoch = Epoch::parse(utc).unwrap();
        let eop = EarthOrientation {
            ut1_minus_utc_s: *dut1,
            xp_rad: *xp,
            yp_rad: *yp,
        };
        let ours = earth::gcrs_to_itrs_matrix(epoch, &eop).unwrap();
        let err = angle_between(ours, mat(m));
        worst = worst.max(err);
        assert!(
            err < earth::MODEL_ACCURACY_RAD,
            "{utc}: {:.2} mas",
            err / MAS
        );
    }
    eprintln!(
        "worst Earth orientation error vs SOFA: {:.2} mas",
        worst / MAS
    );
    // Keep the documented bound honest: not more than 10× the measured error.
    assert!(worst > earth::MODEL_ACCURACY_RAD / 10.0);
}

#[test]
fn iau_moon_and_mars_match_spice() {
    for (name, model, refs) in [
        ("Moon", iau::MOON, data::MOON),
        ("Mars", iau::MARS, data::MARS),
    ] {
        let mut worst = 0.0f64;
        for (et, m) in refs {
            let epoch = Epoch::from_tdb_seconds_since_j2000(*et).unwrap();
            let err = angle_between(model.icrf_to_body_matrix(epoch), mat(m));
            worst = worst.max(err);
        }
        eprintln!(
            "worst {name} orientation error vs SPICE: {:.4} mas",
            worst / MAS
        );
        // Limited only by f64 TDB seconds (≈0.5 µs at 3e9 s) times the spin rate.
        assert!(worst < 0.05 * MAS, "{name}: {:.4} mas", worst / MAS);
    }
}

/// Checks that a transform's angular velocity matches the numerical
/// derivative of its rotation, by comparing a transformed fixed point's
/// velocity with finite differences.
fn check_angular_velocity(
    t_at: impl Fn(Epoch) -> Transform,
    epoch: Epoch,
    radius_m: f64,
    tol_m_s: f64,
) {
    let h = 1.0;
    let p = Vec3::new(0.6, -0.48, 0.64) * radius_m;
    let pos = |dt: f64| t_at(epoch.add_seconds(dt).unwrap()).apply_position(p);
    let numeric = (pos(h) - pos(-h)) / (2.0 * h);
    let (_, analytic) = t_at(epoch).apply(p, Vec3::ZERO);
    assert!(
        (numeric - analytic).norm() < tol_m_s,
        "numeric {numeric:?} analytic {analytic:?}"
    );
}

#[test]
fn angular_velocities_match_finite_differences() {
    let eop = EarthOrientation::from_bulletin(-0.1, 0.2, 0.3);
    for utc in ["1990-05-01T00:00:00Z", "2026-11-19T17:00:00Z"] {
        let e = Epoch::parse(utc).unwrap();
        // Neglected precession–nutation rates are ~1e-11 rad/s → ~1e-4 m/s at 6400 km.
        check_angular_velocity(|t| earth::itrf_to_gcrf(t, &eop).unwrap(), e, 6.4e6, 1e-3);
        // IAU models include every rate term, so agreement is to rounding.
        // IAU models include every rate term; the residual is finite-difference
        // truncation and f64 epoch rounding (< 1e-8 of the surface speed).
        check_angular_velocity(
            |t| iau::MOON.body_fixed_to_icrf(t).unwrap(),
            e,
            1.7374e6,
            1e-5,
        );
        check_angular_velocity(
            |t| iau::MARS.body_fixed_to_icrf(t).unwrap(),
            e,
            3.39e6,
            1e-5,
        );
    }
}

#[test]
fn earth_rotation_angle_at_j2000() {
    // At JD 2451545.0 UT1, ERA = 2π·0.7790572732640 (IERS Conventions 2010, eq. 5.15).
    // With UT1 − UTC = 0, 12:00:00 UTC is JD 2451545.0 UT1.
    let e = Epoch::parse("2000-01-01T12:00:00Z").unwrap();
    let era = earth::earth_rotation_angle(e, &EarthOrientation::ZERO).unwrap();
    assert!(
        (era - 2.0 * core::f64::consts::PI * 0.779_057_273_264_0).abs() < 1e-12,
        "{era}"
    );
    // A UT1 − UTC offset of one second advances ERA by one second of rotation.
    let eop = EarthOrientation {
        ut1_minus_utc_s: 1.0,
        ..EarthOrientation::ZERO
    };
    let era1 = earth::earth_rotation_angle(e, &eop).unwrap();
    assert!((era1 - era - earth::EARTH_ROTATION_RATE_RAD_S).abs() < 1e-12);
}
